/**
 * RoaringBitmap, a compressed alternative to the BitSet.
 *
 * <pre>
 * {@code
 *      import org.roaringbitmap.*;
 *
 *      //...
 *
 *      RoaringBitmap rr = RoaringBitmap.bitmapOf(1,2,3,1000);
 *      RoaringBitmap rr2 = new RoaringBitmap();
 *      for(int k = 4000; k<4255;++k) rr2.add(k);
 *      RoaringBitmap rror = RoaringBitmap.or(rr, rr2);
 *
 *      //...
 *      DataOutputStream wheretoserialize = ...
 *      rr.runOptimize(); // can help compression
 *      rr.serialize(wheretoserialize);
 * }
 * </pre>
 *
 * Integers are added in unsigned sorted order. That is, they are treated as unsigned integers (see
 * Java 8's Integer.toUnsignedLong function).
 * Up to 4294967296 integers
 * can be stored.
 *
 *
 *
 */
public class RoaringBitmap
    implements Cloneable,
        Serializable,
        Iterable<Integer>,
        Externalizable,
        ImmutableBitmapDataProvider,
        BitmapDataProvider,
        AppendableStorage<Container> {

  private class RoaringIntIterator implements PeekableIntIterator {
    private final char startingContainerIndex;
    private int hs = 0;

    private PeekableCharIterator iter;

    private int pos = 0;

    public RoaringIntIterator() {
      this.startingContainerIndex = findStartingContainerIndex();
      nextContainer();
    }

    char findStartingContainerIndex() {
      return 0;
    }

    @Override
    public PeekableIntIterator clone() {
      try {
        RoaringIntIterator x = (RoaringIntIterator) super.clone();
        if (this.iter != null) {
          x.iter = this.iter.clone();
        }
        return x;
      } catch (CloneNotSupportedException e) {
        return null; // will not happen
      }
    }

    @Override
    public boolean hasNext() {
      return pos < RoaringBitmap.this.highLowContainer.size();
    }

    @Override
    public int next() {
      final int x = iter.nextAsInt() | hs;
      if (!iter.hasNext()) {
        ++pos;
        nextContainer();
      }
      return x;
    }

    private void nextContainer() {
      final int containerSize = RoaringBitmap.this.highLowContainer.size();
      if (pos < containerSize) {
        final int index = (pos + startingContainerIndex) % containerSize;
        iter = RoaringBitmap.this.highLowContainer.getContainerAtIndex(index).getCharIterator();
