        int cardinalityOfLastContainer = this.getCardinality(z);
        int sizeOfLastContainer =
            BufferUtil.getSizeInBytesFromCardinalityEtc(cardinalityOfLastContainer, 0, false);
        pos += sizeOfLastContainer;
      }
