    // before the binary search, we optimize for frequent cases
    if ((size == 0) || (keys[size - 1] == x)) {
      return size - 1;
    }
    // no luck we have to go through the list
    return this.binarySearch(0, size, x);
  }

  protected char getKeyAtIndex(int i) {
    return this.keys[i];
  }

  @Override
  public int hashCode() {
    int hashvalue = 0;
    for (int k = 0; k < this.size; ++k) {
      hashvalue = 31 * hashvalue + keys[k] * 0xF0F0F0 + values[k].hashCode();
    }
    return hashvalue;
  }

  /**
   * Validate the RoaringArray. This is useful for checking a recently
   * deserialized RoaringArray.
   * @return true if the RoaringArray is valid
   */
  public boolean validate() {
    for (int k = 0; k < size; ++k) {
      if (k > 0 && keys[k - 1] >= keys[k]) {
        return false;
      }
      if (values[k] == null) {
        return false;
      }
      if (!values[k].validate()) {
