    if (count <= 8) {
      return binarySearch(firstBytes, 0, count, k);
    } else {
      int pos = binarySearch(firstBytes, 0, 8, k);
      if (pos != ILLEGAL_IDX) {
        return pos;
      } else {
        byte[] secondBytes = LongUtils.toBDBytes(secondV);
        pos = binarySearch(secondBytes, 0, (count - 8), k);
