  // make sure there is capacity for at least k more elements
  protected void extendArray(int k) {
    // size + 1 could overflow
    if (this.size + k > this.keys.length) {
      int newCapacity;
      if (this.keys.length < 1024) {
        newCapacity = 2 * (this.size + k);
      } else {
        newCapacity = 5 * (this.size + k) / 4;
      }
      this.keys = Arrays.copyOf(this.keys, newCapacity);
      this.values = Arrays.copyOf(this.values, newCapacity);
    }
  }

  @Override
  public int getCardinality(int i) {
    return getContainerAtIndex(i).getCardinality();
  }

  @Override
  public int getContainerIndex(char x) {
    return Util.searchForContains(keys, size, x);
  }

  @Override
  public MappeableContainer getContainerAtIndex(int i) {
    return this.values[i];
  }

  @Override
  public MappeableContainerPointer getContainerPointer() {
    return getContainerPointer(0);
  }

  @Override
  public MappeableContainerPointer getContainerPointer(final int startIndex) {
    return new MappeableContainerPointer() {
      int k = startIndex;

      @Override
      public void advance() {
        ++k;
      }

      @Override
      public MappeableContainerPointer clone() {
        try {
          return (MappeableContainerPointer) super.clone();
        } catch (CloneNotSupportedException e) {
          return null; // will not happen
        }
      }

      @Override
      public int compareTo(MappeableContainerPointer o) {
        if (key() != o.key()) {
          return (key()) - (o.key());
        }
        return o.getCardinality() - this.getCardinality();
      }

      @Override
      public int getCardinality() {
        return getContainer().getCardinality();
      }

      @Override
      public MappeableContainer getContainer() {
        if (k >= MutableRoaringArray.this.size) {
          return null;
        }
        return MutableRoaringArray.this.values[k];
      }

      @Override
      public int getSizeInBytes() {
        return getContainer().getArraySizeInBytes();
      }

      @Override
      public boolean hasContainer() {
        return 0 <= k && k < MutableRoaringArray.this.size;
      }

      @Override
      public boolean isBitmapContainer() {
        return getContainer() instanceof MappeableBitmapContainer;
      }

      @Override
      public boolean isRunContainer() {
        return getContainer() instanceof MappeableRunContainer;
      }

      @Override
      public char key() {
        return MutableRoaringArray.this.keys[k];
      }

      @Override
      public void previous() {
        --k;
      }
    };
  }

  // involves a binary search
  @Override
  public int getIndex(char x) {
    // before the binary search, we optimize for frequent cases
    if ((size == 0) || (keys[size - 1] == x)) {
      return size - 1;
    }
    // no luck we have to go through the list
    return this.binarySearch(0, size, x);
  }

  @Override
  public char getKeyAtIndex(int i) {
    return this.keys[i];
  }

  @Override
  public boolean equals(Object o) {
    if (o instanceof PointableRoaringArray) {
      PointableRoaringArray srb = (PointableRoaringArray) o;
      if (srb.size() != this.size()) {
        return false;
      }
      MappeableContainerPointer cp = this.getContainerPointer();
      MappeableContainerPointer cpo = srb.getContainerPointer();
      while (cp.hasContainer() && cpo.hasContainer()) {
        if (cp.key() != cpo.key()) {
          return false;
        }
        if (!cp.getContainer().equals(cpo.getContainer())) {
          return false;
        }
        cp.advance();
        cpo.advance();
      }
      return true;
    }
    return false;
  }

  @Override
  public int hashCode() {
    int hashvalue = 0;
    for (int k = 0; k < this.size; ++k) {
      hashvalue = 31 * hashvalue + keys[k] * 0xF0F0F0 + values[k].hashCode();
    }
    return hashvalue;
  }

  @Override
  public boolean hasRunCompression() {
    for (int k = 0; k < size; ++k) {
      MappeableContainer ck = values[k];
      if (ck instanceof MappeableRunContainer) {
        return true;
      }
    }
    return false;
  }

  protected int headerSize() {
    if (hasRunCompression()) {
      if (size < NO_OFFSET_THRESHOLD) { // for small bitmaps, we omit the offsets
        return 4 + (size + 7) / 8 + 4 * size;
      }
      return 4 + (size + 7) / 8 + 8 * size; // - 4 because we pack the size with the cookie
    } else {
      return 4 + 4 + 8 * size;
    }
  }

  // insert a new key, it is assumed that it does not exist
  protected void insertNewKeyValueAt(int i, char key, MappeableContainer value) {
    extendArray(1);
    System.arraycopy(keys, i, keys, i + 1, size - i);
    System.arraycopy(values, i, values, i + 1, size - i);
    keys[i] = key;
    values[i] = value;
    size++;
  }

  @Override
  public void readExternal(ObjectInput in) throws IOException, ClassNotFoundException {
    deserialize(in);
  }

  protected void removeAtIndex(int i) {
    System.arraycopy(keys, i + 1, keys, i, size - i - 1);
    keys[size - 1] = 0;
    System.arraycopy(values, i + 1, values, i, size - i - 1);
    values[size - 1] = null;
    size--;
  }

  static final int MERGE_OR = 0;
  static final int MERGE_XOR = 1;
  static final int MERGE_LAZY_OR = 2;

  /**
   * Finishes an in-place union/xor/lazy-union ({@code op}) once the receiver's structure must
   * change, merging both suffixes into fresh arrays in one pass. Avoids the per-key insert/remove
   * shift, which is quadratic when keys are interleaved.
   *
   * <p>{@code [0, dst)} is already final and copied over. {@code left}/{@code right} are the
   * receiver/source scan positions. For a union {@code dst == left}; xor may pass
   * {@code dst < left} to drop an emptied container. Source-only containers are cloned; the source
   * is read through {@link PointableRoaringArray} as it may be memory-mapped.
   */
  void mergeBulk(PointableRoaringArray other, int dst, int left, int right, int op) {
    final int length1 = this.size;
    final int length2 = other.size();

    // exact result size for union, tight upper bound for xor
    int distinct = 0;
    int l = left;
    int r = right;
    while (l < length1 && r < length2) {
      char k1 = this.keys[l];
      char k2 = other.getKeyAtIndex(r);
      if (k1 < k2) {
        l++;
      } else if (k1 > k2) {
        r++;
      } else {
        l++;
        r++;
      }
      distinct++;
    }
    distinct += (length1 - l) + (length2 - r);
    final int total = dst + distinct;

    char[] newKeys = new char[total];
    MappeableContainer[] newValues = new MappeableContainer[total];
    System.arraycopy(this.keys, 0, newKeys, 0, dst);
    System.arraycopy(this.values, 0, newValues, 0, dst);
    int pos = dst;

    while (left < length1 && right < length2) {
      char k1 = this.keys[left];
      char k2 = other.getKeyAtIndex(right);
      if (k1 < k2) {
        newKeys[pos] = k1;
        newValues[pos] = this.values[left];
        pos++;
        left++;
      } else if (k1 > k2) {
        newKeys[pos] = k2;
        newValues[pos] = other.getContainerAtIndex(right).clone();
        pos++;
        right++;
      } else {
        MappeableContainer c;
        if (op == MERGE_XOR) {
          c = this.values[left].ixor(other.getContainerAtIndex(right));
        } else if (op == MERGE_LAZY_OR) {
          c = this.values[left].toBitmapContainer().lazyIOR(other.getContainerAtIndex(right));
        } else {
          c = this.values[left].ior(other.getContainerAtIndex(right));
        }
        if (op != MERGE_XOR || !c.isEmpty()) {
          newKeys[pos] = k1;
          newValues[pos] = c;
          pos++;
        }
        left++;
        right++;
      }
    }
    while (left < length1) {
      newKeys[pos] = this.keys[left];
      newValues[pos] = this.values[left];
      pos++;
      left++;
    }
    while (right < length2) {
      newKeys[pos] = other.getKeyAtIndex(right);
      newValues[pos] = other.getContainerAtIndex(right).clone();
      pos++;
      right++;
    }

    this.keys = newKeys;
    this.values = newValues;
    this.size = pos;
  }

  protected void removeIndexRange(int begin, int end) {
    if (end <= begin) {
