package org.roaringbitmap;

import static java.lang.Long.numberOfTrailingZeros;

import java.io.DataInput;
import java.io.IOException;
import java.util.Arrays;

/**
 * Various useful methods for roaring bitmaps.
 */
public final class Util {

  /**
   * optimization flag: whether to use hybrid binary search: hybrid formats
   * combine a binary search with a sequential search
   */
  public static final boolean USE_HYBRID_BINSEARCH = true;

  /**
   * Skips exactly n bytes of the input. {@link DataInput#skipBytes} may skip fewer bytes than
   * requested (e.g., with a {@code javax.crypto.CipherInputStream}); the remaining bytes are
   * then consumed one at a time.
   *
   * @param in the input
   * @param n the number of bytes to skip
   * @throws java.io.EOFException if the input ends before n bytes are skipped
   * @throws IOException if an I/O error occurs
   */
  public static void skipFully(DataInput in, int n) throws IOException {
    for (int remaining = n - in.skipBytes(n); remaining > 0; remaining--) {
      in.readByte();
    }
  }

  /**
   * Add value "offset" to all values in the container, producing
   * two new containers. The existing container remains unchanged.
   * The new container are not converted, so they need to be checked:
   * e.g., we could produce two bitmap containers having low cardinality.
   * @param source source container
   * @param offsets value to add to each value in the container
   * @return return an array made of two containers
   */
  public static Container[] addOffset(Container source, char offsets) {
    if (source instanceof ArrayContainer) {
      return addOffsetArray((ArrayContainer) source, offsets);
    } else if (source instanceof BitmapContainer) {
      return addOffsetBitmap((BitmapContainer) source, offsets);
    } else if (source instanceof RunContainer) {
      return addOffsetRun((RunContainer) source, offsets);
    }
    throw new RuntimeException("unknown container type");
  }

  private static Container[] addOffsetArray(ArrayContainer source, char offsets) {
    int splitIndex;
    if (source.first() + offsets > 0xFFFF) {
      splitIndex = 0;
    } else if (source.last() + offsets < 0xFFFF) {
      splitIndex = source.cardinality;
    } else {
      splitIndex =
          Util.unsignedBinarySearch(
              source.content, 0, source.cardinality, (char) (0x10000 - offsets));
      if (splitIndex < 0) {
        splitIndex = -splitIndex - 1;
      }
    }

    ArrayContainer low = splitIndex == 0 ? new ArrayContainer() : new ArrayContainer(splitIndex);
    ArrayContainer high =
        source.cardinality - splitIndex == 0
            ? new ArrayContainer()
            : new ArrayContainer(source.cardinality - splitIndex);

    int lowCardinality = 0;
