    return 2 + 4 * this.nbrruns; // "array" includes its size
  }

  @Override
  public int getCardinality() {
    int sum = nbrruns; // lengths are returned -1
    for (int k = 1; k < nbrruns * 2; k += 2) {
      sum += valueslength[k];
    }
    return sum;
  }

